export function businessKind(name){for(const [kind,re] of Object.entries(categories))if(re.test(name))return kind;return 'apparel';}
const fashionTypes=new Set(['shirt','hoodie','cardigan','jacket','pants','shorts','hat','belt','scarf']);
const allowed={apparel:p=>fashionTypes.has(p.type),shoes:p=>['shoes','sandals'].includes(p.type),bags:p=>['bag','crossbody','backpack','duffel','wallet'].includes(p.type),beauty:p=>['perfume','skincare','lipstick','makeup','mascara'].includes(p.type),jewelry:p=>['watch','digitalwatch','ring','necklace','bracelet','earrings'].includes(p.type),tech:p=>['earbuds','headphones','speaker','tracker','stylus','mouse','keyboard','charger','cable','massager','vacuum'].includes(p.type),home:p=>['bottle','tumbler','candle','mug','home','coffee-machine','stationery','blanket','glassware'].includes(p.type),toys:p=>['buildingtoy','cardgame','toy','plush'].includes(p.type),books:p=>['book','stationery'].includes(p.type),eyewear:p=>p.type==='sunglasses',food:p=>['food','drink'].includes(p.type)};
const mixBrands=/Macy|Nordstrom|Bloomingdale|Neiman Marcus|Saks OFF|Ross|Marshalls|Target|DICK|Champs|JD|Foot Locker|Finish Line|Journeys|Shoe Palace|Footwork|GNC|Vitamin|Cosmetics Company|Perfumania|Fragrance|Perfume|Kestan|Local Market|Open Market|As Seen On TV|Optimus|Spencer|Zales|Kay Jewelers|Kevin Jewelers|Ben Bridge|Swiss Watch|Tourneau|Bucherer|Watch City|Torre/i;
const colors=['#789384','#a78369','#748d9a','#a58a9e','#998d67'];
const hash=s=>[...s].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7);
export const isServiceStore=st=>['service','visitor','entertainment','auto','gallery'].includes(st?.businessKind);
export function buildLegacyStorefronts(stores,products,photos){
 const core=stores.slice(),base=products.slice(),seeds=STORE_PRODUCT_SEEDS.map((p,i)=>({...p,id:p.id||'real-v11-'+i,price:Math.round(p.priceUSD*100),retail:Math.round(p.priceUSD*100),sizes:p.sizes?.length?p.sizes:['One size'],color:p.color||'#9f9989',material:p.material||'Real named product. Photographed variant and simulated game sizing can differ.',assetKey:p.id||'real-v11-'+i,seed:true}));
 for(const p of seeds)if(p.photo)photos[p.id]=p.photo;
 const all=[...base,...seeds],brandIndex=new Map();for(const p of all){for(const key of new Set([brandFamily(p.brand),brandFamily(p.merchant||p.retailer||p.brand)])){if(!brandIndex.has(key))brandIndex.set(key,[]);brandIndex.get(key).push(p);}}
 for(const [mallId,source]of Object.entries(CENTER_DIRECTORIES)){const mall=MALLS.find(m=>m.id===mallId),tier=MALLS.indexOf(mall),coreByKey=new Map(core.filter(st=>mall.sections.some(d=>d.stores.includes(st.id))).map(st=>{const t=matchingTenant(mallId,st.id,core);return t&&gameStoreFloor(mall,st.id,core)===tenantFloor(mallId,t)?[t.key,st]:[null,null];}));for(const t of source.tenants){const floor=tenantFloor(mallId,t),existing=coreByKey.get(t.key);if(existing)continue;
  const id=mallId+'-tenant-'+(t.key||normalizeName(t.name)),kind=businessKind(t.name),family=brandFamily(t.name),section=mall.sections[hash(id)%mall.sections.length],st={id,name:t.name,tier,district:section.id,mallId,floor,tenantKey:t.key,branch:true,businessKind:kind,color:colors[hash(id)%colors.length],light:'#eee7d8',npc:['Alex','Riley','Morgan','Jamie','Taylor'][hash(id)%5],sub:isServiceStore({businessKind:kind})?'SERVICES & EXPERIENCES':'THE REAL PRODUCT EDIT',policy:30,source:t.url||t.source||source.source};
  let selected=[];if(!isServiceStore(st)){const own=brandIndex.get(family)||[];selected=own.filter(p=>photos[p.id]);if(!selected.length){const predicate=allowed[kind]||allowed.apparel;selected=all.filter(p=>photos[p.id]&&predicate(p));if(kind==='eyewear'&&!selected.length)selected=all.filter(p=>photos[p.id]&&['hat','watch','digitalwatch'].includes(p.type));if(kind==='books'&&!selected.length)selected=all.filter(p=>photos[p.id]&&['stationery','cardgame'].includes(p.type));const luxury=/Gucci|Prada|Dior|Chanel|Celine|Loewe|Fendi|Hermès|Saint Laurent|Balenciaga|Balmain|Alaïa|Brunello|Loro Piana|ZEGNA|Zegna|Givenchy|Giorgio Armani|Brioni|Kiton|Tom Ford|McQueen|Dolce|Versace|Valentino|Lanvin|Cartier|Graff|Harry Winston|Patek|Audemars|Vacheron|Lange|Hublot|Breitling|Rolex|Tudor|Piaget|Panerai|Chopard|Mikimoto|Buccellati|Bvlgari|Messika|Delvaux|Moynat|Roger Dubuis/.test(t.name);if(luxury){const high=selected.filter(p=>p.price>=30000);if(high.length)selected=high;}selected=selected.map(p=>({p,score:hash(id+p.id)})).sort((a,b)=>a.score-b.score).slice(0,12).map(v=>v.p);st.assortmentBasis=mixBrands.test(t.name)?'multibrand-game':'guest-capsule';}else {st.assortmentBasis='brand-models';selected=selected.slice(0,24);}const identities=new Set();selected=selected.filter(p=>{const k=p.brand+' · '+p.name;if(identities.has(k))return false;identities.add(k);return true;});
   for(const p of selected){const pid=id+'::'+p.id,q={...p,id:pid,store:id,modelId:p.modelId||p.id,finalSale:p.finalSale||['food','drink'].includes(p.type),assortmentBasis:st.assortmentBasis,observedPriceDate:p.observedPriceDate||(/official|published/i.test(p.priceBasis||'')&&!/simulated reference|cached/i.test(p.priceBasis||'')?p.checkedOn:undefined)};delete q.photo;products.push(q);photos[pid]=photos[p.id];}
  }
  st.greeting=isServiceStore(st)?'Come inside, meet the team and choose a service or activity. All payments use game money.':st.assortmentBasis==='brand-models'?'Browse real named designs from this brand. Game stock and prices can differ from the real store.':st.assortmentBasis==='guest-capsule'?'This playable shop hosts a guest capsule of real photographed products. The brands on each label are the actual makers; this capsule is a game arrangement, not this retailer’s verified collection.':'Browse a curated multibrand game assortment of real photographed items. Availability and prices are simulated.';
  stores.push(st);if(!section.stores.includes(id))section.stores.push(id);
 }}
 return {core,seeds};
}
